import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Meeting.css';

import { useLocation } from 'react-router-dom';

function Meeting() {
  const location = useLocation();
  const { isMicEnabled, isCamEnabled } = location.state;
  const userVideo = useRef();
  const navigate = useNavigate();


  useEffect(() => {
    // Request access to the user's camera and microphone
    navigator.mediaDevices.getUserMedia({ video: isCamEnabled, audio: isMicEnabled })
      .then(stream => {
        // Set the source of the video element to the user's stream
        userVideo.current.srcObject = stream;
      })
      .catch(err => {
        console.error('Error accessing media devices.', err);
      });
  }, [isMicEnabled, isCamEnabled]);

  const handleCamera = () => {
    // Implement camera functionality
  };

  const handleMicrophone = () => {
    // Implement microphone functionality
  };

  const handleLeave = () => {
    navigate('/');
  };

  return (
    <div className="App">
      <main>
        <video ref={userVideo} id="localVideo" autoPlay muted></video>
        <video id="remoteVideo" autoPlay></video>
        <div>
          <button id="cameraButton" onClick={handleCamera}>Camera</button>
          <button id="microphoneButton" onClick={handleMicrophone}>Microphone</button>
          <button id="callButton" onClick={handleLeave}>Leave</button>
        </div>
      </main>
    </div>
  );
}

export default Meeting;
